definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '15'))
    timeout(time: 60, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/businessplanner.git'
      }
    }

    stage('Docker Preflight') {
      steps {
        sh '''
          docker version
          docker compose version
          curl -fsS -I http://localhost:5001/v2/ || true
        '''
      }
    }

    // App service images are localhost:5001/.../businessplanner/<svc>:latest.
    // --ignore-buildable skips the keycloak/elasticsearch/frontend/sso services
    // that build locally. Best-effort: an image missing from the registry must
    // not abort the deploy.
    stage('Pull Service Images') {
      steps {
        sh '''
          docker compose pull --ignore-buildable || docker compose pull || true
        '''
      }
    }

    stage('Deploy Stack') {
      steps {
        sh '''
          set -e
          docker compose up -d --build --remove-orphans
        '''
      }
    }

    stage('Status') {
      steps {
        sh 'docker compose ps'
      }
    }
  }

  post {
    success {
      echo 'businessplanner stack deployed - portal: http://localhost:8892'
    }
    always {
      cleanWs()
    }
  }
}
